async function orderAction(button,url,body={}){try{if(button)button.disabled=true;const result=await api(url,{method:'POST',body:JSON.stringify(body)});if(currentUser.role==='DRIVER'&&Number.isInteger(result.balanceAmd))currentUser.balanceAmd=result.balanceAmd;message('#appMessage',result.commissionAmd>0?'Պատվերն ընդունվեց։ 25% միջնորդավճարը գանձվեց հաշվեկշռից։':'Պատվերի կարգավիճակը թարմացվեց։');if(currentUser.role==='DRIVER')await driverView();else await customerView()}catch(e){if(button)button.disabled=false;message('#appMessage',e.message,true)}}
setInterval(async()=>{if(!currentUser||document.hidden)return;try{if(currentUser.role==='DRIVER'&&$('#openOrders')){const data=await api('/api/orders/open');const fresh=(data.orders||[]).filter(order=>!knownDriverOpenOrderIds?.has(order.id)&&!order.isTest);if(knownDriverOpenOrderIds===null)knownDriverOpenOrderIds=new Set((data.orders||[]).map(order=>order.id));else{if(fresh.length)notifyDriverOfNewOrders(fresh);knownDriverOpenOrderIds=new Set((data.orders||[]).map(order=>order.id))}renderOrders($('#openOrders'),data.orders,'open');if($('#openOrderCount'))$('#openOrderCount').textContent=(data.orders||[]).length;const mineData=await api('/api/orders/mine');renderOrders($('#driverReadyOrder'),(mineData.orders||[]).filter(order=>['ARRIVED','IN_PROGRESS'].includes(order.status)).sort((a,b)=>({ARRIVED:0,IN_PROGRESS:1}[a.status]-({ARRIVED:0,IN_PROGRESS:1}[b.status]))),'mine');renderOrders($('#driverAcceptedOrders'),(mineData.orders||[]).filter(order=>order.status==='ACCEPTED').sort((a,b)=>{const schedule=o=>o.scheduleType==='NOW'?0:(o.scheduledAt?Date.parse(o.scheduledAt):Number.MAX_SAFE_INTEGER);return schedule(a)-schedule(b)}),'mine')}if(currentUser.role==='ADMIN'&&$('#adminTestOrders')){const data=await api('/api/admin/orders'),box=$('#adminTestOrders');box.innerHTML=data.orders.length?data.orders.map(o=>'<article class="order"><div class="rowline"><strong>'+money(o.fareAmd)+'</strong><span class="test-order-badge">ՓՈՐՁՆԱԿԱՆ</span><span class="muted">'+esc(({OPEN:'Բաց',ACCEPTED:'Ընդունված',IN_PROGRESS:'Ընթացքում',COMPLETED:'Կատարված',CANCELLED:'Չեղարկված'})[o.status]||o.status)+'</span></div><p>Հաճախորդ՝ '+esc(o.customer?.name||'Ադմին')+'<br>Սկիզբ՝ '+esc(o.pickupAddress)+'<br>Նպատակակետ՝ '+esc(o.destinationAddress)+'<br>Վարորդ՝ '+esc(o.driver?.name||'Դեռ նշանակված չէ')+'</p></article>').join(''):'<p class="empty-state">Փորձնական պատվերներ դեռ չկան։</p>'}}catch(_){ }},5000);
