 const root=document.documentElement,style=root.style;if(c.accentColor)style.setProperty('--gold2',c.accentColor);if(c.buttonColor)style.setProperty('--gold',c.buttonColor);if(c.textColor)style.setProperty('--white',c.textColor);if(c.pageBackgroundColor)document.body.style.backgroundColor=c.pageBackgroundColor;
 const hero=$('.hero');if(hero){if(c.heroBackgroundColor)hero.style.backgroundColor=c.heroBackgroundColor;if(c.heroImageUrl)hero.style.backgroundImage='linear-gradient(rgba(0,0,0,.48),rgba(0,0,0,.62)),url("'+c.heroImageUrl.replace(/["\\]/g,'')+'")';if(c.heroVideoUrl&&!hero.querySelector('video.site-hero-video')){const video=document.createElement('video');video.className='site-hero-video';video.src=c.heroVideoUrl;video.autoplay=true;video.muted=true;video.loop=true;video.playsInline=true;video.setAttribute('aria-hidden','true');hero.prepend(video)}}
